<template>
  <section class="reference-list" aria-label="国家订货参考清单">
    <el-alert v-if="auth.authorizationStale" title="账号权限正在刷新，请刷新授权后重新读取补货参考。" type="warning" :closable="false" />
    <p>清单以国家＋普通商品SKU汇总。普通商品直接销量与组合商品折算组件销量参与计算；虚拟商品和组合商品本身不生成采购建议。</p>
    <div class="strategy-summary" v-if="strategy"><strong>{{ strategy.name || '国家补货策略' }}</strong><span>订货间隔 {{ strategy.cycle_days }} 天</span><span>预计到仓 {{ strategy.lead_days }} 天</span><span>安全库存 {{ strategy.safety_days }} 天</span><span>权重 7/15/30 天：{{ weightsLabel }}</span><small>策略版本 {{ strategy.version ?? strategy.id ?? '—' }} · 销量截止 {{ salesEnd || '昨天' }}</small></div>
    <el-alert v-if="strategyNotice" :title="strategyNotice" type="warning" :closable="false" />
    <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" />
    <div class="reference-actions">
      <el-select v-model="sourceKind" aria-label="建议类型" :disabled="blocked"><el-option label="常规补货" value="cycle"/><el-option label="季节／活动补货" value="season"/></el-select>
      <el-date-picker v-if="sourceKind==='season'" v-model="activityStart" type="date" value-format="YYYY-MM-DD" placeholder="活动开始日期" aria-label="活动开始日期" :disabled="blocked" />
      <el-date-picker v-if="sourceKind==='season'" v-model="activityEnd" type="date" value-format="YYYY-MM-DD" placeholder="活动结束日期" aria-label="活动结束日期" :disabled="blocked" />
      <el-input-number v-if="sourceKind==='season'" v-model="activityFactor" :min="0.01" :max="20" :precision="2" :step="0.1" aria-label="活动需求系数" :disabled="blocked" />
      <el-select v-model="analysisMode" aria-label="参考分析方式" @change="reset"><el-option label="国家汇总" value="country"/><el-option label="按平台分析" value="platform"/></el-select>
      <el-select v-if="analysisMode==='platform'" v-model="platformType" placeholder="选择平台" aria-label="参考分析平台" @change="reset"><el-option v-for="option in platformOptions" :key="option.platform_type" :label="option.name" :value="option.platform_type"/></el-select>
    </div>
    <p v-if="analysisMode==='platform'" class="muted">平台销量用于贡献分析；共享库存、采购供应和运营需求仍按国家汇总扣减一次。</p>
    <div class="reference-actions"><el-button type="primary" :loading="loading" :disabled="blocked || !strategy?.active" @click="generate">生成补货参考</el-button><el-button v-if="jobId && ['queued','running'].includes(jobStatus)" :disabled="loading" @click="cancelJob">取消计算</el-button><el-button v-if="jobId && ['failed','cancelled','expired'].includes(jobStatus)" :disabled="blocked || loading" @click="generate">重新计算</el-button><el-tag v-if="jobStatus" :type="jobStatus==='completed'?'success':jobStatus==='failed'?'danger':['queued','running'].includes(jobStatus)?'warning':'info'">{{jobStatusLabel}}</el-tag></div>
    <el-progress v-if="jobId && ['queued','running'].includes(jobStatus)" :percentage="progressPercent" :status="jobStatus==='failed'?'exception':undefined" :format="progressText" />
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <div v-if="jobStatus==='failed'" class="job-error"><span>{{jobError || '计算失败，请重试。'}}</span><el-button type="primary" :disabled="blocked || loading" @click="generate">重试</el-button></div>
    <template v-if="jobStatus==='completed'">
      <p class="muted">计算观察期间 {{ dateTime(observationStart) }} 至 {{ dateTime(observationEnd || generatedAt) }} · 销量截止 {{ salesEnd || '—' }} · 策略版本 {{ jobStrategyVersion || strategy?.version || '—' }}。{{ formula }} {{ revalidationNote }}</p>
      <div class="result-summary"><div><strong>{{ number(summary.positive_count) }}</strong><span>建议新增</span></div><div><strong>{{ number(summary.unknown_count) }}</strong><span>数据待核对</span></div><div><strong>{{ number(summary.awaiting_procurement_count) }}</strong><span>已有需求待采购</span></div><div><strong>{{ number(summary.arrival_risk_count) }}</strong><span>到货风险</span></div><div><strong>{{ number(totalRows) }}</strong><span>当前筛选结果</span></div></div>
      <div class="reference-actions result-filters"><el-input v-model="search" clearable placeholder="搜索新旧SKU／商品名称" aria-label="参考商品搜索" @keyup.enter="loadRows(0)" :disabled="loading"/><el-select v-model="filter" aria-label="建议筛选" @change="loadRows(0)" :disabled="loading"><el-option label="建议新增量大于0" value="positive"/><el-option label="全部商品" value="all"/><el-option label="无需新增" value="zero"/><el-option label="数据待核对" value="unknown"/></el-select><el-select v-model="riskFilter" aria-label="风险筛选" placeholder="全部风险" @change="loadRows(0)" :disabled="loading"><el-option label="全部风险" value=""/><el-option label="已有需求待采购" value="awaiting_procurement"/><el-option label="需补货" value="replenish"/><el-option label="到货前有缺口" value="arrival_gap"/><el-option label="已缺货" value="out_of_stock"/><el-option label="新品／无销量" value="new_or_zero_sales"/><el-option label="数据待核对" value="data_check"/></el-select><el-button :loading="loading" @click="loadRows(0)">查询</el-button></div>
      <div class="table-scroll" v-loading="loading"><el-table :data="rows" border empty-text="当前筛选下暂无商品">
        <el-table-column label="商品图片" width="100"><template #default="{row}"><OperatingProductImageV2 :sku-id="row.sku_id" :source="row.image_preview_url || row.product_details?.image_url || ''"/></template></el-table-column>
        <el-table-column label="SKU / 商品" min-width="200"><template #default="{row}"><DocumentSkuV2 :sku="row.sku_code || row.sku" :legacy-sku-code="row.legacy_sku_code"/><small>{{row.product_name}}</small><el-tag v-if="row.product_status" size="small" :type="productStatusType(row.product_status)">{{productStatusLabel(row.product_status)}}</el-tag></template></el-table-column>
        <el-table-column label="预测日销量" width="115"><template #default="{row}">{{ number(row.forecast_daily_sales) }}</template></el-table-column>
        <el-table-column v-if="analysisMode==='platform'" label="平台销量贡献（不代入建议量）" min-width="240"><template #default="{row}"><small v-for="window in platformRows(row)" :key="window.period">{{window.period}}：{{number(window.units)}} 件 · 日均 {{number(window.daily_units)}} 件</small><small>仅作平台贡献分析；补货建议仍按国家汇总计算。</small></template></el-table-column>
        <el-table-column label="库存与供应" min-width="185"><template #default="{row}"><div>可用 {{ number(row.available_stock) }} · 有效到货 {{ number(row.valid_incoming ?? row.in_transit_stock) }}</div><div>已提交需求 {{ number(row.submitted_demand) }}</div><div>草稿预留 {{ number(row.draft_reserved_demand) }}</div></template></el-table-column>
        <el-table-column label="在库可售" width="105"><template #default="{row}">{{ days(row.on_hand_days ?? row.coverage_days) }}</template></el-table-column>
        <el-table-column label="最近预计到仓" min-width="145"><template #default="{row}">{{ etaDate(row.next_eta) }}<small v-if="row.next_eta?.quantity">{{ number(row.next_eta.quantity) }} 件</small></template></el-table-column>
        <el-table-column label="采购落实缺口" width="120"><template #default="{row}">{{ number(row.replenishment_gap) }}</template></el-table-column>
        <el-table-column label="建议新增量" width="115"><template #default="{row}"><strong>{{ number(row.suggested_quantity) }}</strong></template></el-table-column>
        <el-table-column label="风险 / 依据" min-width="205"><template #default="{row}"><el-tag size="small" :type="riskType(row.risk_level)">{{ riskLabel(row.risk_level) }}</el-tag><small v-for="issue in row.issues || []" :key="issue">{{issueLabel(issue)}}</small><el-button link type="primary" @click="openEvidence(row)">查看公式与来源</el-button></template></el-table-column>
        <el-table-column v-if="audience==='operator'" label="选择" width="70" fixed="right"><template #default="{row}"><el-checkbox :model-value="!!chosen[row.sku_id]" :disabled="loading || !Number(row.suggested_quantity) || Number(row.suggested_quantity)<0" :aria-label="`选择${row.sku_code || row.sku}`" @change="value=>toggle(row,value)"/></template></el-table-column>
      </el-table></div>
      <div class="reference-actions"><el-button v-if="audience==='operator'" :disabled="loading" @click="selectPage">勾选本页建议商品</el-button><el-button v-if="audience==='operator'" :disabled="!selectedRows.length" @click="chosen={}">清空勾选</el-button><span v-if="audience==='operator'">已选 {{selectedRows.length}} 个SKU（跨筛选和分页保留，最多100个）</span><el-button v-if="audience==='operator'" type="primary" :disabled="blocked || jobStatus!=='completed' || !jobId || !selectedRows.length" @click="emitSelection">带入运营订货草稿</el-button><el-button v-else type="primary" @click="$emit('procurement')">前往采购协同</el-button><el-pagination v-model:current-page="page" :page-size="pageSize" :total="totalRows" layout="total, prev, pager, next" @current-change="loadCurrentPage" /></div>
    </template>
    <el-dialog v-model="evidenceVisible" title="补货计算依据" width="min(720px,96vw)"><template v-if="evidenceRow"><h4>{{ evidenceRow.sku_code || evidenceRow.sku }} · {{ evidenceRow.product_name }}</h4><p>{{ evidence(evidenceRow).daily_sales_formula || formula }}</p><el-table :data="salesRows(evidenceRow)" border><el-table-column prop="period" label="参考期间"/><el-table-column prop="units" label="销量"/><el-table-column prop="daily_units" label="日均销量"/><el-table-column label="权重"><template #default="{row}">{{weightPercent(row.weight)}}</template></el-table-column></el-table><el-table v-if="evidenceRow.platform_analysis?.windows" :data="platformRows(evidenceRow)" border><el-table-column prop="period" label="平台分析期间"/><el-table-column prop="units" label="该平台销量"/><el-table-column prop="daily_units" label="该平台日均销量"/></el-table><small v-if="evidenceRow.platform_analysis" class="muted">平台 {{evidenceRow.platform_analysis.platform_type}} 的销量只用于贡献分析，不参与国家建议量计算。</small><el-descriptions :column="2" border><el-descriptions-item label="目标覆盖天数">{{ evidence(evidenceRow).target_days ?? '—' }}</el-descriptions-item><el-descriptions-item label="目标备货量">{{ number(evidence(evidenceRow).target_stock) }}</el-descriptions-item><el-descriptions-item label="提醒线预测需求（到仓前＋安全库存）">{{ number(evidence(evidenceRow).reminder_stock) }}</el-descriptions-item><el-descriptions-item label="提醒线期间预计到货">{{ number(evidence(evidenceRow).reminder_incoming) }}</el-descriptions-item><el-descriptions-item label="是否触发订货提醒">{{ yesNo(evidence(evidenceRow).needs_replenishment) }}</el-descriptions-item><el-descriptions-item label="首次预计缺货日期">{{ shortageLabel(evidenceRow) }}</el-descriptions-item><el-descriptions-item label="到仓前是否有缺货">{{ yesNo(evidence(evidenceRow).arrival_gap) }}</el-descriptions-item><el-descriptions-item label="可用库存">{{ number(evidence(evidenceRow).available_stock ?? evidenceRow.available_stock) }}</el-descriptions-item><el-descriptions-item label="目标期有效到货">{{ number(evidence(evidenceRow).valid_incoming ?? evidenceRow.valid_incoming) }}</el-descriptions-item><el-descriptions-item label="采购落实缺口">{{ number(evidence(evidenceRow).replenishment_gap ?? evidence(evidenceRow).gap ?? evidenceRow.replenishment_gap) }}</el-descriptions-item><el-descriptions-item label="建议新增量">{{ number(evidence(evidenceRow).suggested_quantity ?? evidenceRow.suggested_quantity) }}</el-descriptions-item><el-descriptions-item label="已提交需求">{{ number(evidence(evidenceRow).submitted_demand ?? evidenceRow.submitted_demand) }}</el-descriptions-item><el-descriptions-item label="草稿预留需求">{{ number(evidence(evidenceRow).draft_reserved_demand ?? evidenceRow.draft_reserved_demand) }}</el-descriptions-item></el-descriptions><p><strong>公式代入：</strong>{{ substitutedFormula(evidenceRow) }}</p><p>趋势变化 {{ percent(evidenceRow.sales_trend_rate) }} · 在库可售 {{ days(evidenceRow.on_hand_days) }} · 含供应覆盖 {{ days(evidenceRow.supply_cover_days) }}</p><el-table :data="evidenceRow.warehouses || evidenceRow.warehouse_rows || []" border empty-text="没有仓库明细"><el-table-column prop="name" label="仓库"/><el-table-column prop="available_qty" label="可用库存"/><el-table-column prop="snapshot_at" label="快照时间"/></el-table><small v-for="issue in evidenceRow.issues || []" :key="issue" class="issue">{{issueLabel(issue)}}</small></template></el-dialog>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useAuthStore } from '../../stores/auth';
import { cancelReplenishmentJob, createReplenishmentJob, fetchReplenishmentJob, fetchReplenishmentJobRows, fetchReplenishmentStrategy } from '../../api/replenishmentStrategyV2';
import { cockpitActorKey } from '../../utils/cockpitDraft';
import OperatingProductImageV2 from './OperatingProductImageV2.vue';
import DocumentSkuV2 from './DocumentSkuV2.vue';

const props = defineProps({ parameters: { type: Object, required: true }, disabled: Boolean, audience: { type: String, default: 'operator' }, issueLabel: { type: Function, default: value => value } });
const emit = defineEmits(['select','procurement','strategy','source-change']);
const auth = useAuthStore();
const blocked = computed(() => props.disabled || auth.authorizationStale);
const sourceKind=ref(props.parameters.source_kind || 'cycle'), activityStart=ref(''), activityEnd=ref(''), activityFactor=ref(1), analysisMode=ref('country'), platformType=ref(''), platformOptions=ref([]), strategy=ref(null), strategyNotice=ref(''), salesEnd=ref('');
const search=ref(''), filter=ref('positive'), riskFilter=ref(''), rows=ref([]), chosen=ref({}), page=ref(1), pageSize=ref(20), totalRows=ref(0), summary=ref({}), loading=ref(false), error=ref(''), loadError=ref(''), generatedAt=ref(''), formula=ref('');
const jobId=ref(''),jobStatus=ref(''),jobProcessed=ref(0),jobTotal=ref(0),jobError=ref(''),jobStrategyVersion=ref(''),observationStart=ref(''),observationEnd=ref(''),revalidationNote=ref('');
const evidenceVisible=ref(false), evidenceRow=ref(null); let requestSequence=0,strategySequence=0,pollTimer=null,pollController=null,jobGeneration=0;
const selectedRows=computed(()=>Object.values(chosen.value));
const progressPercent=computed(()=>jobTotal.value?Math.min(100,Math.floor(jobProcessed.value*100/jobTotal.value)):0);
const jobStatusLabel=computed(()=>({queued:'排队中',running:'计算中',completed:'计算完成',failed:'计算失败',cancelled:'已取消',expired:'结果已过期'}[jobStatus.value]||''));
const weightPercent=value=>value==null?'—':`${Number(value).toLocaleString('zh-CN',{maximumFractionDigits:2})}%`;
const weightsLabel=computed(()=>[7,15,30].map(day=>weightPercent(strategy.value?.sales_weights?.[day] ?? strategy.value?.sales_weights?.[String(day)])).join(' / '));
const number=value=>value==null?'—':Number(value).toLocaleString('zh-CN',{maximumFractionDigits:2});
const dateTime=value=>{if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('zh-CN',{hour12:false});};
const days=value=>value==null?'—':`${number(value)} 天`;
const etaDate=value=>value&&typeof value==='object'?(value.expected_date||value.date||'—'):(value||'—');
const percent=value=>value==null?'—':`${(Number(value)*100).toFixed(1)}%`;
const yesNo=value=>value==null?'待核对':(value===true||value==='true'?'是':'否');
const riskLabel=value=>({data_check:'数据待核对',new_or_zero_sales:'新品／无销量待评估',out_of_stock:'已缺货',arrival_gap:'到货前有缺口',replenish:'需补货',manual_review:'停售／暂停状态，人工复核',normal:'正常'}[value]||'待核对');
const riskType=value=>({data_check:'danger',new_or_zero_sales:'info',out_of_stock:'danger',arrival_gap:'warning',replenish:'warning',manual_review:'warning',normal:'success'}[value]||'info');
const lifecycleStatusMap={new:'新品',new_product:'新品',active:'正常',draft:'草稿',discontinued:'已停产',slow_moving:'滞销',clearance_candidate:'清仓候选',clearance:'清仓',archived:'已归档',unknown:'待维护'};
const salesStatusMap={on_sale:'销售中',selling:'销售中',not_listed:'未上架',paused:'暂停销售',stopped:'已停止销售',unknown:'待维护'};
const productStatusLabel=value=>{const [lifecycle,sales]=String(value||'').split('/');return [lifecycle&&`生命周期：${lifecycleStatusMap[lifecycle]||lifecycle}`,sales&&`销售状态：${salesStatusMap[sales]||sales}`].filter(Boolean).join('／')||'待维护';};
const productStatusType=value=>/discontinued|stopped|paused/.test(String(value))?'danger':/slow_moving|clearance/.test(String(value))?'warning':/active|on_sale|selling/.test(String(value))?'success':'info';
function evidence(row){return row.calculation_evidence||row.formula_evidence||{};}
function shortageLabel(row){const e=evidence(row);if(row.risk_level==='data_check')return '数据待核对';if(e.first_shortage_date)return e.first_shortage_date;if(row.risk_level==='new_or_zero_sales')return '近期无销量，暂不推算缺货日';return e.needs_replenishment==null?'数据待核对':'覆盖期内未预测到缺货';}
function substitutedFormula(row){const e=evidence(row),keys=['target_stock','available_stock','valid_incoming','submitted_demand','draft_reserved_demand'];if(keys.some(key=>e[key]==null)||e.suggested_quantity==null)return `${e.formula||'ceil(max(0,T-I-P-O-Q))'}（数据待核对）`;return `向上取整［最大值（0，${keys.map(key=>number(e[key])).join('－')}）］＝${number(e.suggested_quantity)}`;}
function salesRows(row){const sales=evidence(row).sales||{};return [7,15,30].map(day=>({period:`近${day}天`,...(sales[day]||sales[String(day)]||{})}));}
function platformRows(row){const windows=row.platform_analysis?.windows||{};return [7,15,30].map(day=>({period:`近${day}天`,...(windows[day]||windows[String(day)]||{})}));}
function issueLabel(code){return props.issueLabel(code);}
function stopPolling(){if(pollTimer){clearTimeout(pollTimer);pollTimer=null;}pollController?.abort();pollController=null;}
function reset({clearJob=true}={}){const oldId=jobId.value,shouldCancel=clearJob&&oldId&&['queued','running'].includes(jobStatus.value);requestSequence++;jobGeneration++;stopPolling();loading.value=false;if(shouldCancel)cancelReplenishmentJob(oldId).catch(()=>{});rows.value=[];chosen.value={};page.value=1;totalRows.value=0;summary.value={};error.value='';jobError.value='';evidenceVisible.value=false;evidenceRow.value=null;if(clearJob){jobId.value='';jobStatus.value='';jobProcessed.value=0;jobTotal.value=0;generatedAt.value='';formula.value='';jobStrategyVersion.value='';observationStart.value='';observationEnd.value='';revalidationNote.value='';}}
async function loadStrategy(){const token=++strategySequence;strategy.value=null;loadError.value='';reset();if(blocked.value||!props.parameters.country_id)return;try{const response=await fetchReplenishmentStrategy(props.parameters.country_id);if(token!==strategySequence)return;if(!response?.success)throw new Error(response?.message||'国家补货策略读取失败。');const data=response.data||{},candidate=data.strategy||data;const isConfigured=data.configured!==false&&!!candidate?.id;strategy.value=isConfigured?candidate:null;if(!isConfigured)strategyNotice.value='该国家尚未配置补货策略，请先到供应链设置维护。';else strategyNotice.value=strategy.value.active===false?'当前国家策略已停用。':'';salesEnd.value=data.sales_end||'';emit('strategy',{...(strategy.value||{}),sales_end:salesEnd.value,configured:isConfigured});}catch(e){if(token===strategySequence)loadError.value=e.message||'国家补货策略读取失败。';}}
watch(()=>String(props.parameters.country_id||''),loadStrategy,{immediate:true});
watch(()=>JSON.stringify([props.parameters.source_kind,props.parameters.analysis_mode,props.parameters.platform_type,props.parameters.activity_start,props.parameters.activity_end,props.parameters.activity_factor,props.parameters.strategy_id,props.parameters.sales_end,props.parameters.exclude_operating_order_id]),()=>{if(jobId.value)reset();},{flush:'sync'});
watch(()=>JSON.stringify([cockpitActorKey(auth.currentUser),auth.authorizationStale]),()=>{strategySequence++;requestSequence++;loading.value=false;strategy.value=null;strategyNotice.value='';loadError.value='';error.value='';platformOptions.value=[];platformType.value='';salesEnd.value='';reset();if(!auth.authorizationStale)loadStrategy();},{flush:'sync'});
watch(()=>props.parameters.source_kind,value=>{if(['cycle','season'].includes(value))sourceKind.value=value;});
watch(sourceKind,value=>{if(props.parameters.source_kind!==value)emit('source-change',value);reset();});
watch(()=>JSON.stringify([activityStart.value,activityEnd.value,activityFactor.value,analysisMode.value,platformType.value]),reset);
onBeforeUnmount(()=>{const id=jobId.value,active=id&&['queued','running'].includes(jobStatus.value);requestSequence++;strategySequence++;jobGeneration++;stopPolling();if(active)cancelReplenishmentJob(id).catch(()=>{});});
function requestBody(){return {country_id:Number(props.parameters.country_id),...(strategy.value?.id?{strategy_id:strategy.value.id}:{}),...(salesEnd.value?{sales_end:salesEnd.value}:{}),...(props.parameters.exclude_operating_order_id?{exclude_operating_order_id:props.parameters.exclude_operating_order_id}:{}),source_kind:sourceKind.value,analysis_mode:analysisMode.value,...(analysisMode.value==='platform'?{platform_type:platformType.value}:{}),...(sourceKind.value==='season'?{activity_start:activityStart.value||null,activity_end:activityEnd.value||null,activity_factor:Number(activityFactor.value)}:{})};}
async function generate(){if(blocked.value||!props.parameters.country_id||!strategy.value?.id||strategy.value.active===false)return;if(analysisMode.value==='platform'&&!platformType.value){error.value='请先选择平台；可先生成国家汇总参考以读取平台选项。';return;}if(sourceKind.value==='season'&&(!activityStart.value||!activityEnd.value||activityStart.value>activityEnd.value||Number(activityFactor.value)<0.01||Number(activityFactor.value)>20)){error.value='请填写有效的活动起止日期，系数范围为0.01至20。';return;}reset();const generation=jobGeneration,token=++requestSequence;loading.value=true;error.value='';try{const response=await createReplenishmentJob(requestBody());if(token!==requestSequence||generation!==jobGeneration)return;if(!response?.success)throw new Error(response?.message||'补货参考任务提交失败。');const data=response.data||{};jobId.value=String(data.id||'');if(!jobId.value)throw new Error('任务已提交，但服务未返回任务编号。');jobStatus.value=data.status||'queued';updateJob(data);if(jobStatus.value==='completed')await loadRows(0,generation);else startPolling(generation);}catch(e){if(token===requestSequence){error.value=e.message||'补货参考任务提交失败。';jobStatus.value='failed';jobError.value=error.value;}}finally{if(token===requestSequence)loading.value=false;}}
function updateJob(data={}){jobStatus.value=data.status||jobStatus.value;jobProcessed.value=Number(data.processed??jobProcessed.value);jobTotal.value=Number(data.total??jobTotal.value);jobError.value=data.error||data.error_message||'';generatedAt.value=data.updated_at||data.created_at||generatedAt.value;jobStrategyVersion.value=data.strategy_version??jobStrategyVersion.value;observationStart.value=data.created_at||observationStart.value;observationEnd.value=data.updated_at||observationEnd.value;salesEnd.value=data.parameters?.sales_end||salesEnd.value;formula.value=data.formula||formula.value;revalidationNote.value=data.revalidation_note||'';if(data.platform_options)platformOptions.value=data.platform_options;if(data.counts)summary.value={...summary.value,positive_count:data.counts.positive??summary.value.positive_count,unknown_count:data.counts.unknown??summary.value.unknown_count,zero_count:data.counts.zero??summary.value.zero_count,awaiting_procurement_count:data.counts.awaiting_procurement??summary.value.awaiting_procurement_count,arrival_risk_count:data.counts.arrival_gap??summary.value.arrival_risk_count};}
function progressText(){return `${number(jobProcessed.value)} / ${number(jobTotal.value)} 条`;}
function startPolling(generation,delay=2000){stopPolling();pollTimer=setTimeout(()=>pollJob(generation,delay),delay);}
function handleTerminal(status,message){jobStatus.value=status;jobError.value=message;rows.value=[];chosen.value={};evidenceVisible.value=false;evidenceRow.value=null;totalRows.value=0;summary.value={};stopPolling();}
async function pollJob(generation,delay){pollTimer=null;if(generation!==jobGeneration||!jobId.value||!['queued','running'].includes(jobStatus.value))return;pollController=new AbortController();try{const response=await fetchReplenishmentJob(jobId.value,{signal:pollController.signal});if(generation!==jobGeneration)return;if(!response?.success){if([403,404,410].includes(response?.http_status)){handleTerminal(response.http_status===410||response.http_status===404?'expired':'failed',response.message||'任务已失效或当前账号无权访问，请重新生成。');return;}throw new Error(response?.message||'读取计算进度失败');}const data=response.data||{};updateJob(data);if(['queued','running'].includes(jobStatus.value))startPolling(generation,Math.min(5000,delay+1000));else if(jobStatus.value==='completed')await loadRows(0,generation);else if(['failed','cancelled','expired'].includes(jobStatus.value))handleTerminal(jobStatus.value,jobError.value||({failed:'任务计算失败，请检查数据后重试。',cancelled:'任务已取消。',expired:'结果已过期，请重新生成。'}[jobStatus.value]));}catch(e){if(generation===jobGeneration&&e?.name!=='CanceledError'&&e?.name!=='AbortError'){error.value=e.message||'读取计算进度失败';startPolling(generation,Math.min(5000,delay+1000));}}finally{if(generation===jobGeneration)pollController=null;}}
async function loadRows(pageIndex=page.value-1,generation=jobGeneration){if(!jobId.value||jobStatus.value!=='completed'||blocked.value||generation!==jobGeneration)return;const token=++requestSequence;loading.value=true;error.value='';try{const params={quantity_filter:filter.value,risk_filter:riskFilter.value||undefined,search:search.value.trim()||undefined,limit:pageSize.value,offset:Math.max(0,pageIndex)*pageSize.value};const response=await fetchReplenishmentJobRows(jobId.value,params,{signal:(pollController=new AbortController()).signal});if(token!==requestSequence||generation!==jobGeneration)return;if(!response?.success){if([403,404,410].includes(response?.http_status)||response?.code==='JOB_EXPIRED'){handleTerminal(response?.http_status===403?'failed':'expired',response.message||'结果已失效或当前账号无权访问，请重新生成。');return;}throw new Error(response?.message||'读取补货结果失败');}const data=response.data||{};if(data.status&&data.status!=='completed'){handleTerminal(data.status,data.status==='expired'?'结果已过期，请重新生成。':'任务状态已变化，请重新生成。');return;}rows.value=data.rows||[];totalRows.value=Number(data.count??0);if(data.counts)summary.value={...summary.value,positive_count:data.counts.positive??summary.value.positive_count,unknown_count:data.counts.unknown??summary.value.unknown_count,zero_count:data.counts.zero??summary.value.zero_count,awaiting_procurement_count:data.counts.awaiting_procurement??summary.value.awaiting_procurement_count,arrival_risk_count:data.counts.arrival_gap??summary.value.arrival_risk_count};page.value=Math.floor(params.offset/pageSize.value)+1;}catch(e){if(token===requestSequence)error.value=e.message||'读取补货结果失败';}finally{if(token===requestSequence){loading.value=false;pollController=null;}}}
function loadCurrentPage(value){return loadRows(value-1);}
async function cancelJob(){if(!jobId.value||!['queued','running'].includes(jobStatus.value))return;const id=jobId.value;jobGeneration++;stopPolling();jobStatus.value='cancelled';loading.value=true;try{await cancelReplenishmentJob(id);}finally{loading.value=false;}}
function toggle(row,value){const copy={...chosen.value};if(value){if(Number(row.suggested_quantity)>0&&!copy[row.sku_id]){if(Object.keys(copy).length>=100){error.value='最多选择100个SKU，请分单处理。';return;}copy[row.sku_id]=row;}}else delete copy[row.sku_id];chosen.value=copy;}
function selectPage(){rows.value.filter(row=>Number(row.suggested_quantity)>0).forEach(row=>toggle(row,true));}
function emitSelection(){if(blocked.value||jobStatus.value!=='completed'||!jobId.value||!selectedRows.value.length)return;emit('select',{parameters:{...requestBody(),job_id:jobId.value,activity_start:activityStart.value||null,activity_end:activityEnd.value||null,activity_factor:Number(activityFactor.value)},rows:selectedRows.value});}
function openEvidence(row){evidenceRow.value=row;evidenceVisible.value=true;}
defineExpose({generate,loadRows,reset,toggle,selectPage,emitSelection,rows,strategy,selectedRows,requestBody,search,filter,riskFilter,analysisMode,platformType,sourceKind,jobId,jobStatus,jobProcessed,jobTotal,progressPercent,summary,totalRows,page,openEvidence,evidenceRow,evidenceVisible,etaDate,weightPercent,productStatusLabel,evidence,salesRows,platformRows,yesNo});
</script>
